private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 128) {
            sb.append((char) b);
            i++;
        } else {
            int leadingOnes = Integer.numberOfLeadingZeros(b ^ 0xFF);
            if (leadingOnes < 5) {
                if (i + leadingOnes > bb.remaining()) {
                    return -1; // Not enough bytes for the sequence
                }
                char c = 0;
                for (int j = 1; j < leadingOnes; j++) {
                    int nextB = bb.get() & 0xFF;
                    c = (char) ((c << 6) | (nextB & 0x3F));
                }
                if ((c & 0xFF80) == 0) {
                    sb.append((char) c);
                    i += leadingOnes;
                } else {
                    return -1; // Invalid UTF-8 sequence
                }
            } else {
                return -1; // Invalid UTF-8 lead byte
            }
        }
    }
    return i;
}
