    try {
        while (bb.hasRemaining()) {
            char c = (char) bb.get();
            if (c < 0x80) {
                sb.append(c);
            } else if ((c & 0xE0) == 0xC0) {
                int b1 = bb.get() & 0x3F;
                sb.append((char) ((c & 0x1F) << 6 | b1));
            } else if ((c & 0xF0) == 0xE0) {
                int b1 = bb.get() & 0x3F;
                int b2 = bb.get() & 0x3F;
                sb.append((char) ((c & 0x0F) << 12 | b1 << 6 | b2));
            } else if ((c & 0xF8) == 0xF0) {
                int b1 = bb.get() & 0x3F;
                int b2 = bb.get() & 0x3F;
                int b3 = bb.get() & 0x3F;
                char surrogate = (char) ((c & 0x07) << 18 | b1 << 12 | b2 << 6 | b3);
                if (surrogate < 0xD800 || surrogate > 0xDBFF) {
                    sb.append(surrogate);
                } else {
                    c = (char) bb.get();
                    int b4 = bb.get() & 0x3F;
                    char partner = (char) ((c & 0x3F) << 10 | b4);
                    sb.appendCodePoint(0x10000 + ((surrogate - 0xD800) << 10) | partner);
                }
            }
        }
    } catch (Exception e) {
