private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        byte[] octets = new byte[4];
        int sequenceLength = 1;

        if ((bb.get(i) & 0x80) == 0) {
            // Single-byte character
            sequenceLength = 1;
        } else if ((bb.get(i) & 0xE0) == 0xC0) {
            // Two-byte character
            sequenceLength = 2;
        } else if ((bb.get(i) & 0xF0) == 0xE0) {
            // Three-byte character
            sequenceLength = 3;
        } else if ((bb.get(i) & 0xF8) == 0xF0) {
            // Four-byte character
            sequenceLength = 4;
        }

        for (int j = 0; j < sequenceLength; j++) {
            octets[j] = bb.get(i + j);
        }

        String decodedString = new String(octets, 0, sequenceLength, StandardCharsets.UTF_8);
        sb.append(decodedString);

        return i + sequenceLength;
    } catch (Exception e) {
        return i; // Return current index if decoding fails
    }
}

