@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Construct a complete bipartite graph
    Set<String> partition1 = new HashSet<>();
    Set<String> partition2 = new HashSet<>();

    // Populate the partitions with unique keys from resultMap
    for (String key : resultMap.keySet()) {
        if (key.hashCode() % 2 == 0) {
            partition1.add(key);
        } else {
            partition2.add(key);
        }
    }

    // Add vertices to the target graph
    for (String vertex : partition1) {
        target.addVertex(vertex);
    }
    for (String vertex : partition2) {
        target.addVertex(vertex);
    }

    // Add edges between vertices of different partitions
    for (String v1 : partition1) {
        for (String v2 : partition2) {
