public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    LinkedBuffer tmp = buffer;
    try {
        byte[] data = schema.toBytes(message);
        int size = data.length;
        if (size >= 127) {
            int hi = size >>> 7;
            out.write((byte) (size | 0x80));
            if (hi >= 127) {
                int hi2 = hi >>> 7;
                out.write((byte) (hi | 0x80));
                if (hi2 >= 127) {
                    out.write((byte) (hi2 | 0x80));
                    out.write((byte) hi2);
                } else {
                    out.write((byte) hi2);
                }
                out.write((byte) hi);
            } else {
                out.write((byte) hi);
            }
            out.write((byte) size);
        } else {
            out.write((byte) size);
        }
        out.write(data);
        return size + 1 + (data.length > 127 ? 1 : 0) + (data.length > 16383 ? 1 : 0) + (data.length > 2097151 ? 1 : 0);
    } finally {
        tmp.clear();
    }
}
