protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        long splitCount = (duration / FETCH_DATA_DURATION) + 1;
        long splitDuration = duration / splitCount;
        for (int i = 0; i < splitCount; i++) {
            long splitStart = start + i * splitDuration;
            long splitEnd = (i + 1) * splitDuration < end ? (i + 1) * splitDuration : end;
            timeRanges.add(new TimeRange(splitStart, splitEnd));
        }
    } else {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}
