static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    if (dayStep == 1) {
        return timeBucket; // No change needed
    } else if (dayStep > 1) {
        long newDay = day - (day % dayStep);
        if (newDay == 0) {
            newDay += dayStep;
            if (--month == 0) {
                month = 12;
                --year;
            }
        }
        return year * 10000 + month * 100 + newDay;
    } else {
        throw new IllegalArgumentException("Invalid dayStep");
    }
}

