import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    try {
        Path path = decode ? Paths.get(u.getPath()) : Paths.get(java.net.URLDecoder.decode(u.getPath(), "UTF-8"));
        pathSegments = new ArrayList<>(path.getNameCount());
        for (int i = 0; i < path.getNameCount(); i++) {
            pathSegments.add(new PathSegmentImpl(path.getName(i).toString()));
        }
    } catch (URISyntaxException e) {
        e.printStackTrace();
    }
    return pathSegments;
}

List<PathSegmentImpl> function(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

