private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    for (String key : jsonObject.keySet()) {
        JsonElement element = jsonObject.get(key);
        if (element.isJsonPrimitive()) {
            content.put(key, element.getAsString());
        } else if (element.isJsonObject()) {
            content.put(key, buildContent(element.getAsJsonObject()));
        } else if (element.isJsonArray()) {
            JsonArray array = element.getAsJsonArray();
            List<Object> list = new ArrayList<>();
            for (JsonElement arrayElement : array) {
                if (arrayElement.isJsonPrimitive()) {
                    list.add(arrayElement.getAsString());
                } else if (arrayElement.isJsonObject()) {
                    list.add(buildContent(arrayElement.getAsJsonObject()));
                }
            }
            content.put(key, list);
        }
    }
    return content;
}
