public class GraphPath<V, E> {
    private Set<E> edges;
    private V startVertex;
    private V endVertex;

    public GraphPath(Set<E> edges, V startVertex, V endVertex) {
        this.edges = edges;
        this.startVertex = startVertex;
        this.endVertex = endVertex;
    }

    public Set<E> getEdges() {
        return edges;
    }

    public V getStartVertex() {
        return startVertex;
    }

    public V getEndVertex() {
        return endVertex;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    GraphPath<V, E> path = new GraphPath<>(tour, null, null);
    // Determine the start and end vertices
    for (E edge : tour) {
        path.startVertex = graph.getEdgeSource(edge);
        path.endVertex = graph.getEdgeTarget(edge);
    }
    return path;
}

