private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '_' && i + 1 < input.length() && input.charAt(i + 1) == '_') {
            sb.append('.');
            i++;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
