private void pop(final String descriptor){
    // Dictionary to hold the type sizes
    Map<Character, Integer> typeSizes = new HashMap<>();
    typeSizes.put('Z', 1); // boolean
    typeSizes.put('C', 2); // char
    typeSizes.put('S', 2); // short
    typeSizes.put('I', 4); // int
    typeSizes.put('J', 8); // long
    typeSizes.put('F', 4); // float
    typeSizes.put('D', 8); // double
    typeSizes.put('B', 1); // byte
    typeSizes.put('V', 0); // void
    typeSizes.put('L', 4); // reference
    typeSizes.put('[', 4); // array reference

    int numPopped = 0;
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i++);
        if (c == '(') {
            // Parse parameter types of a method descriptor
            while (descriptor.charAt(i) != ')') {
                i += parseTypeSize(descriptor, i, typeSizes);
            }
            i++; // Skip ')'
        } else {
            i += parseTypeSize(descriptor, i, typeSizes);
        }
        numPopped += 1;
    }

    // Pop the abstract types from the output frame stack
    for (int j = 0; j < numPopped; j++) {
        // Pop operation here
    }
}

private int parseTypeSize(String descriptor, int index, Map<Character, Integer> typeSizes) {
    char c = descriptor.charAt(index);
    if (c == 'L') {
        // Skip class name
        while (descriptor.charAt(index) != ';') {
            index++;
        }
        index++;
    } else if (c == '[') {
        // Skip array dimensions
        while (descriptor.charAt(index) == '[') {
            index++;
        }
    }
    return typeSizes.get(c);
}
