public static int indexOfExtension(String filename) {
    int extensionPos = filename.lastIndexOf('.');
    int lastSeparatorPos = indexOfLastSeparator(filename);
    if (extensionPos == -1 || extensionPos < lastSeparatorPos) {
        return -1;
    }
    return extensionPos;
}

private static int indexOfLastSeparator(String filename) {
    int lastSeparatorPos = -1;
    int index = 0;
    while ((index = filename.indexOf('/', index)) != -1) {
        lastSeparatorPos = index;
        index++;
    }
    index = 0;
    while ((index = filename.indexOf('\\', index)) != -1) {
        lastSeparatorPos = index;
        index++;
    }
    return lastSeparatorPos;
}
