int function(InputStream stream) throws IOException {
    int b = stream.read();
    if (b == -1) {
        return 0;
    }
    int fieldNumber = ((b & 0x7f) << 3) | ((b >>> 4) & 0x07);
    if ((b & 0x80) == 0) {
        return fieldNumber;
    }
    int tag = 0;
    while ((b & 0x80) != 0) {
        tag <<= 7;
        tag |= (b & 0x7f);
        if ((b = stream.read()) == -1) {
            throw new IOException("Truncated tag at " + tag);
        }
    }
    tag <<= 7;
    tag |= (b & 0x7f);
    return fieldNumber | tag;
}
